def add(p,k,title,stem,opts,why,correct=0,typ='conceptual',difficulty='easy',kind='statement',locator=None,refs=(),**kw):
 q=B.add(p,k,title,stem,[x[0] for x in opts],correct,why,[x[1] for x in opts],typ=typ,difficulty=difficulty,**kw)
 for c in q['citations']:
  c['kind']=kind;c['locator']=f"Lecture39, printed slide{c['physicalPage']-1196}, physical PDF page{c['physicalPage']}: "+(locator or title)
 if refs:q['primaryEvidence']=[dict(title=PRIMARY[t][0],url=PRIMARY[t][1],locator=PRIMARY[t][2],checkedAt=NOW) for t in refs]
 B.save();return q
F_TIME=formula('r=c(t_rx−t_tx)',{'r':'ideal geometric range','c':'vacuum propagation speed','t_rx':'reception time','t_tx':'transmission time'},{'r':'m','c':'m/s','t_rx':'s','t_tx':'s'},['Aligned clocks; propagation corrections and measurement noise neglected.'])
F_PSEUDO=formula('rho_i=||r−s_i||+c delta_t',{'rho_i':'corrected code pseudorange to satellite i','r':'receiver Cartesian position','s_i':'satellite position','c':'light speed','delta_t':'receiver clock offset from system time'},{'rho_i':'m','r':'m','s_i':'m','c':'m/s','delta_t':'s'},['Satellite clock and propagation corrections applied; common receiver clock bias.'])
F_CIRC=formula('(x−x_i)^2+(y−y_i)^2=r_i^2',{'x,y':'unknown planar receiver coordinates','x_i,y_i':'known reference coordinates','r_i':'known range'},{'x,y':'m','x_i,y_i':'m','r_i':'m'},['Exact planar ranges with aligned timing.'])
F_DOP=formula('sigma_position=PDOP sigma_range',{'sigma_position':'3D root-sum-square position standard deviation','PDOP':'position geometry dilution factor','sigma_range':'common individual range standard deviation'},{'sigma_position':'m','PDOP':'dimensionless','sigma_range':'m'},['Linearized full-rank geometry; independent zero-mean equal-variance range errors; no unmodeled bias.'])
