add([1219,1220],'cosmetic-latlon','Cosmetic coordinate conversion','The linked code states lat=28.6139+(300−y)×0.00006 and lon=77.2090+(x−300)×0.00006, rounded to5 decimals. For(x,y)=(400,200), what is the displayed pair?',[
 ('(28.61990,77.21500).','Each relevant difference is+100, so each offset is+0.006 degrees.'),('(28.60790,77.20300).','This reverses both offset signs.'),('(77.21500,28.61990).','This reverses the defined return order(lat,lon).'),('(28.61990,77.20300).','This reverses only the longitude offset.')], 'The arithmetic produces display labels; the code explicitly calls this a cosmetic conversion, not a validated geographic projection.',typ='numerical',difficulty='medium',kind='code',formulas=[formula('lat=LAT0+(300−y)k; lon=LON0+(x−300)k',{'lat,lon':'synthetic displayed coordinates','LAT0,LON0':'reference display coordinates','x,y':'plot coordinates','k':'display scale0.00006'},{'lat,lon':'degrees','LAT0,LON0':'degrees','x,y':'plot units','k':'degrees/plot unit'},['Artificial display conversion only; reference plot coordinate300.'])],steps=['300−200=100 and400−300=100.','100×0.00006=0.006.','Add offsets to28.6139 and77.2090.'],refs=('code',))
